script:
(function () {
  'use strict';
  // Contribution-margin CVP analysis for a multi-product sales mix (mix held constant).
  //   For product i: CM_i = price_i - variable cost_i; mix weight w_i = units_i / total units.
  //   Weighted CM per unit  WCM = sum(w_i x CM_i); weighted CM ratio = total CM / total sales.
  //   Breakeven units (all products) = fixed costs / WCM, split by w_i; breakeven sales =
  //   fixed costs / weighted CM ratio. Units for a target profit = (fixed + target) / WCM.
  //   Operating income = total CM - fixed costs. Degree of operating leverage DOL = CM / operating
  //   income; margin of safety = expected sales - breakeven sales (and MOS % = 1 / DOL).
  //   Sales-change table: every product's units scaled by the same %, so CM scales with sales.
  // Verified (scratchpad b7opt/tests/cm.test.js):
  //   defaults (3 products, $180,000 fixed): sales $545,000, variable costs $299,000, CM $246,000
  //   (45.14%), operating income $66,000; WCM $24.60 per unit, breakeven 7,317.07 units =
  //   $398,780.49 of sales, checked by hand; margin of safety 26.83% = 1 / DOL (3.73x), and a +10%
  //   sales change raises operating income by 37.3% (= DOL x 10%);
  //   one product (price $22.50, variable $13.50, fixed $500) -> breakeven 55.56 units / $1,250,
  //   the textbook single-product result F / (P - V).
  var ROWS = 4;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var units = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
  var CHANGES = [-0.2, -0.1, -0.05, 0, 0.05, 0.1, 0.2];

  function raw(id) { return document.getElementById(id).value.trim(); }
  function num(id) { var v = parseFloat(raw(id)); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function mark(id, bad) { document.getElementById(id).setAttribute('aria-invalid', String(bad)); }
  function pct(x, d) { return (x * 100).toFixed(d === undefined ? 2 : d) + '%'; }
  function signedPct(x) { return Math.abs(x) < 0.00005 ? '0.0%' : (x > 0 ? '+' : '−') + (Math.abs(x) * 100).toFixed(1) + '%'; }
  function signedMoney(x) { return x < -0.005 ? '−' + money.format(-x) : money.format(Math.abs(x) < 0.005 ? 0 : x); }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  // Pure CVP maths for a list of {price, vc, units}.
  function analyse(products, fixed, target) {
    var totalUnits = 0, sales = 0, vcTotal = 0;
    products.forEach(function (p) { totalUnits += p.units; sales += p.price * p.units; vcTotal += p.vc * p.units; });
    var cm = sales - vcTotal;
    var wcm = cm / totalUnits, cmRatio = sales > 0 ? cm / sales : 0;
    var r = { totalUnits: totalUnits, sales: sales, vc: vcTotal, cm: cm, wcm: wcm, cmRatio: cmRatio, oi: cm - fixed };
    if (wcm > 0) {
      r.beUnits = fixed / wcm;
      r.beSales = fixed / cmRatio;
      r.targetUnits = (fixed + target) / wcm;
      r.targetSales = (fixed + target) / cmRatio;
      r.mos = sales - r.beSales;
    }
    r.dol = r.oi > 0 ? cm / r.oi : NaN;
    return r;
  }

  var RESULT_IDS = ['cmBeSales', 'cmBeUnits', 'cmRatio', 'cmWcm', 'cmOi', 'cmDol', 'cmMos', 'cmTargetSales'];
  function clearResults() {
    RESULT_IDS.forEach(function (id) { set(id, '–'); set(id + 'Note', ''); });
    clearBody('cmProducts'); clearBody('cmStatement'); clearBody('cmLeverage');
  }

  function update() {
    var error = document.getElementById('cmError');
    var products = [], problem = '';
    for (var i = 1; i <= ROWS; i++) {
      var ids = ['cmPrice' + i, 'cmVar' + i, 'cmUnits' + i];
      if (raw(ids[0]) === '' && raw(ids[2]) === '') { ids.forEach(function (id) { mark(id, false); }); continue; }
      var p = num(ids[0]), v = num(ids[1]), u = num(ids[2]);
      if (raw(ids[1]) === '') v = 0;
      var bp = isNaN(p) || p <= 0, bv = isNaN(v) || v < 0, bu = isNaN(u) || u < 0;
      mark(ids[0], bp); mark(ids[1], bv); mark(ids[2], bu);
      var name = raw('cmName' + i) || ('Product ' + i);
      if (bp || bv || bu) { problem = problem || 'Check ' + name + ': a price above $0, a variable cost of $0 or more and expected units of 0 or more.'; continue; }
      products.push({ name: name, price: p, vc: v, units: u });
    }
    var fixed = num('cmFixed'), target = raw('cmTarget') === '' ? 0 : num('cmTarget');
    var totalUnits = products.reduce(function (s, p) { return s + p.units; }, 0);
    if (!problem && !products.length) problem = 'Enter at least one product with a price and expected units.';
    else if (!problem && !(totalUnits > 0)) problem = 'Enter expected unit sales for at least one product so the sales mix is known.';
    else if (!problem && (isNaN(fixed) || fixed < 0)) problem = 'Enter fixed costs of $0 or more.';
    else if (!problem && (isNaN(target) || target < 0)) problem = 'Enter a target profit of $0 or more.';
    var r;
    if (!problem) {
      r = analyse(products, fixed, target);
      if (!(r.wcm > 0)) problem = 'At this sales mix the variable costs are at least as high as the prices, so there is no contribution margin and the business can never break even. Raise prices or lower variable costs.';
    }
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    set('cmBeSales', money.format(r.beSales));
    set('cmBeSalesNote', 'Sales that just cover ' + money.format(fixed) + ' of fixed costs at this mix.');
    set('cmBeUnits', units.format(Math.ceil(r.beUnits - 1e-9)));
    set('cmBeUnitsNote', 'Units across all products, in the same mix.');
    set('cmRatio', pct(r.cmRatio));
    set('cmRatioNote', 'Of every sales dollar is left to cover fixed costs.');
    set('cmWcm', money.format(r.wcm));
    set('cmWcmNote', 'Weighted contribution margin per unit sold.');
    set('cmOi', signedMoney(r.oi));
    set('cmOiNote', 'At the expected sales of ' + money.format(r.sales) + '.');
    if (r.oi > 0) {
      set('cmDol', r.dol.toFixed(2) + 'x');
      set('cmDolNote', 'A 10% change in sales moves operating income by about ' + (r.dol * 10).toFixed(1) + '%.');
      set('cmMos', money.format(r.mos));
      set('cmMosNote', pct(r.mos / r.sales, 1) + ' of expected sales could be lost before a loss.');
    } else {
      set('cmDol', '–');
      set('cmDolNote', 'Only meaningful when the expected sales make a profit.');
      set('cmMos', money.format(0));
      set('cmMosNote', 'Expected sales are ' + money.format(r.beSales - r.sales) + ' short of breakeven.');
    }
    set('cmTargetSales', money.format(r.targetSales));
    set('cmTargetSalesNote', units.format(Math.ceil(r.targetUnits - 1e-9)) + ' units in total to earn ' + money.format(target) + '.');

    var pb = clearBody('cmProducts');
    products.forEach(function (p) {
      var w = p.units / r.totalUnits, cmu = p.price - p.vc;
      addRow(pb, [p.name, money.format(p.price), money.format(p.vc), signedMoney(cmu), pct(cmu / p.price, 1), pct(w, 1),
        units.format(Math.ceil(r.beUnits * w - 1e-9)), money.format(r.beUnits * w * p.price), units.format(Math.ceil(r.targetUnits * w - 1e-9))]);
    });

    var st = clearBody('cmStatement');
    addRow(st, ['Sales', money.format(r.sales), '100.0%']);
    addRow(st, ['Less variable costs', money.format(r.vc), pct(r.vc / r.sales, 1)]);
    addRow(st, ['Contribution margin', signedMoney(r.cm), pct(r.cmRatio, 1)]);
    addRow(st, ['Less fixed costs', money.format(fixed), pct(fixed / r.sales, 1)]);
    addRow(st, ['Operating income', signedMoney(r.oi), pct(r.oi / r.sales, 1)]);

    var lv = clearBody('cmLeverage');
    CHANGES.forEach(function (c) {
      var s = r.sales * (1 + c), cmv = r.cm * (1 + c), oi = cmv - fixed;
      var change = r.oi !== 0 ? (oi - r.oi) / Math.abs(r.oi) : 0;
      addRow(lv, [signedPct(c), money.format(s), signedMoney(cmv), signedMoney(oi), r.oi !== 0 ? signedPct(change) : '–']);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cmForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
